import 'package:flutter_test/flutter_test.dart';
import 'package:foodapp_user/models/live_driver_point.dart';
void main(){test('valid real sample; reject old, future, inaccurate and invalid coordinates',(){final now=DateTime.utc(2026,11,5);final p={'latitude':31.9,'longitude':44.4,'accuracy':8,'heading':120,'observedAt':now.toIso8601String()};Map<String,dynamic> data(Map<String,dynamic> patch)=>{'orderId':'o','driverId':'d','location':{...p,...patch}};expect(LiveDriverPoint.parse(data({}),now:now)?.orderId,'o');for(final patch in [{'latitude':double.nan},{'accuracy':101},{'heading':360},{'observedAt':now.subtract(const Duration(seconds:61)).toIso8601String()},{'observedAt':now.add(const Duration(seconds:10)).toIso8601String()}]){expect(LiveDriverPoint.parse(data(patch),now:now),isNull);}});}
